#!/bin/bash
sed -i 's/tools := a.ToolManager.ListTools()/tools := a.ToolManager.ListTools()\n\t\t\tintent := r.URL.Query().Get("intent")\n\t\t\tif intent != "" {\n\t\t\t\t// Apply LazyMCP filtering\n\t\t\t\tmcpTools := make([]*mcp.Tool, 0, len(tools))\n\t\t\t\tfor _, t := range tools {\n\t\t\t\t\tmcpTools = append(mcpTools, t.MCPTool())\n\t\t\t\t}\n\t\t\t\tfilterCfg := middleware.LazyMCPConfig{Enabled: true, Threshold: 0.85}\n\t\t\t\tlazyMid := middleware.NewLazyMCPMiddleware(filterCfg)\n\t\t\t\tfilteredRes := lazyMid.FilterTools(\&mcp.ListToolsResult{Tools: mcpTools}, intent)\n\t\t\t\tmcpTools = filteredRes.Tools\n\t\t\t\t\n\t\t\t\t// Convert back to JSON format, ignoring tool.Tool wrapper since UI just needs the MCP tool\n\t\t\t\tw.Header().Set("Content-Type", "application/json")\n\t\t\t\t_ = json.NewEncoder(w).Encode(mcpTools)\n\t\t\t\treturn\n\t\t\t}/' server/pkg/app/api.go
